+        .filter(|mv| mv.kind == MoveKind::Feed && mv.to.z <= 15.0 + 1e-6)
+        .map(|mv| (mv.to.x - corner.x).hypot(mv.to.y - corner.y))
+        .fold(f64::INFINITY, f64::min);
+    min_dist <= r + 0.02
+}
