+    .expect("circle plan");
+    assert!(circ_plan.reliefs.is_empty(), "circle needs 0 reliefs: {:?}", circ_plan.reliefs);
+    assert!(inside_corners(&circle_reg(256)).is_empty(), "fine circle has no sharp corners");
+}
